"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type ReactNode, useEffect, useId, useState } from "react";

import { cn } from "@/lib/utils";

/**
 * Props for a textarea with a letter limit. Pass `value` to control it, or
 * `defaultValue` to let it hold its own text. `className` styles the wrapper;
 * every other prop reaches the `textarea`.
 */
export type CharacterLimitProps = Omit<
  ComponentPropsWithoutRef<"textarea">,
  "value" | "defaultValue" | "onChange" | "children"
> & {
  label: ReactNode;
  /** The most letters the text should hold. Longer text is flagged, never cut. */
  limit: number;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** The remaining count appears once this few letters are left. */
  showCountAt?: number;
};

const EASE_OUT: Transition = { duration: 0.2, ease: [0.165, 0.84, 0.44, 1] };
const INSTANT: Transition = { duration: 0 };
const SHAKE = { x: [0, -4, 4, -3, 3, 0] };
const SHAKE_TIMING: Transition = { duration: 0.3, ease: "easeOut" };
// A screen reader hears the count once typing pauses, not on every key.
const ANNOUNCE_AFTER = 800;

/**
 * A textarea that shows how much room is left. A ring fills as the person
 * types, the remaining count appears near the end, and past the limit the
 * count goes negative and shakes once. The text itself is never cut.
 */
export function CharacterLimit({
  label,
  limit,
  value,
  defaultValue = "",
  onValueChange,
  showCountAt = 20,
  className,
  id,
  "aria-describedby": describedBy,
  ...textareaProps
}: CharacterLimitProps) {
  const [ownValue, setOwnValue] = useState(defaultValue);
  const [announcement, setAnnouncement] = useState("");
  const ownId = useId();
  const fieldId = id ?? ownId;
  const hintId = `${fieldId}-limit`;
  const reduceMotion = useReducedMotion();

  const text = value ?? ownValue;
  // Counted by code point, so an emoji is one letter, as the person sees it.
  const remaining = limit - Array.from(text).length;
  const over = remaining < 0;
  const showCount = remaining <= showCountAt;

  // The counter shakes once each time the text crosses the limit, not on every key past it.
  const [wasOver, setWasOver] = useState(over);
  const [crossings, setCrossings] = useState(0);
  if (over !== wasOver) {
    setWasOver(over);
    if (over) setCrossings(crossings + 1);
  }

  useEffect(() => {
    let next = "";
    if (over) next = `${-remaining} over the limit`;
    else if (showCount) next = `${remaining} left`;
    const timer = window.setTimeout(() => setAnnouncement(next), ANNOUNCE_AFTER);
    return () => window.clearTimeout(timer);
  }, [over, remaining, showCount]);

  return (
    <div className={cn("flex w-full flex-col gap-2", className)}>
      <label htmlFor={fieldId} className="text-sm font-medium text-foreground">
        {label}
      </label>
      <div
        className={cn(
          "relative rounded-xl border bg-background motion-safe:transition-colors motion-safe:duration-150",
          "has-focus-visible:ring-2 has-focus-visible:ring-ring has-focus-visible:ring-offset-2 has-focus-visible:ring-offset-background",
          over ? "border-destructive" : "border-border",
        )}
      >
        <textarea
          {...textareaProps}
          id={fieldId}
          value={text}
          aria-invalid={over || undefined}
          aria-describedby={describedBy ? `${describedBy} ${hintId}` : hintId}
          onChange={(event) => {
            if (value === undefined) setOwnValue(event.target.value);
            onValueChange?.(event.target.value);
          }}
          className="block min-h-24 w-full resize-none rounded-xl bg-transparent px-3 pt-3 pb-10 text-base text-foreground outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50 sm:text-sm"
        />
        <div
          aria-hidden="true"
          className={cn(
            "pointer-events-none absolute right-3 bottom-2.5 flex items-center gap-2 text-xs font-medium tabular-nums",
            over ? "text-destructive" : "text-muted-foreground",
          )}
        >
          <AnimatePresence initial={false}>
            {showCount ? (
              <motion.span
                initial={reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.8 }}
                transition={EASE_OUT}
                className="flex origin-right"
              >
                <motion.span
                  key={crossings}
                  data-count=""
                  animate={crossings > 0 && over && !reduceMotion ? SHAKE : undefined}
                  transition={SHAKE_TIMING}
                >
                  {remaining}
                </motion.span>
              </motion.span>
            ) : null}
          </AnimatePresence>
          <svg viewBox="0 0 20 20" fill="none" strokeWidth="2.5" className="size-5 -rotate-90">
            <circle cx="10" cy="10" r="8" className="stroke-border" />
            <motion.circle
              cx="10"
              cy="10"
              r="8"
              stroke="currentColor"
              strokeLinecap="round"
              initial={false}
              animate={{ pathLength: Math.min(1, Math.max(0, 1 - remaining / limit)) }}
              transition={reduceMotion ? INSTANT : EASE_OUT}
            />
          </svg>
        </div>
      </div>
      <span id={hintId} className="sr-only">
        Limit of {limit} letters.
      </span>
      <span role="status" className="sr-only">
        {announcement}
      </span>
    </div>
  );
}
